import json

class RagResponseError(Exception):
    def __init__(self, message, code="unknown"):
        super().__init__(message)
        self.code = code

    @classmethod
    def from_response(cls, response):
        try:
            body = response.json()
        except ValueError:
            return cls("RAG server returned invalid JSON.", code="invalid_json")

        error = body.get("error") if isinstance(body, dict) else None
        if isinstance(error, dict) and isinstance(error.get("message"), str):
            return cls(error["message"], code="message_missing")
        if isinstance(error, dict) and isinstance(error.get("code"), str):
            return cls(error["message"], code=error["code"])

        return cls("RAG server returned an unexpected result shape.", code="unexpected_shape")

def ask(question):
    if not _enabled():
        raise RagDisabledError("RAG is disabled.")

    try:
        response = requests.post(
            f"{RAG_SERVER_URL}/query",
            json={"feature": FEATURE, "question": question},
            timeout=REQUEST_TIMEOUT,
        )
    except requests.exceptions.RequestException as exc:
        raise RagUnavailableError(str(exc)) from exc

    if response.status_code != 200:
        # TODO(you): Extract the "code" string from the RAG server's error body, defaulting to "unknown" if missing or malformed.
        error = response.json().get("error")
        if error:
            response_error = RagResponseError.from_response(response)
            raise response_error(response_error.code)

    try:
        body = response.json()
    except ValueError as exc:
        raise RagResponseError("RAG server returned invalid JSON.") from exc

    if not isinstance(body, dict) or set(body) != {"answer", "citations", "confidence"}:
        raise RagResponseError("RAG server returned an unexpected result shape.")

    return body
